/**
 * @summary List upcoming birthdays
 */
export const getListBirthdaysUrl = (params?: ListBirthdaysParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/birthdays?${stringifiedParams}`
    : `/api/birthdays`;
};

export const listBirthdays = async (
  params?: ListBirthdaysParams,
  options?: RequestInit,
): Promise<BirthdayUser[]> => {
  return customFetch<BirthdayUser[]>(getListBirthdaysUrl(params), {
    ...options,
    method: "GET",
  });
};

